CREATE TABLE school_live_classes (
 id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),academic_year_id TEXT NOT NULL REFERENCES academic_years(id),assignment_id TEXT NOT NULL,section_id TEXT NOT NULL REFERENCES sections(id),teacher_user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT,platform TEXT NOT NULL CHECK(platform IN ('google_meet','zoom','microsoft_teams')),meeting_url TEXT NOT NULL,meeting_id TEXT,passcode TEXT,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('scheduled','cancelled')),approval_status TEXT NOT NULL CHECK(approval_status IN ('pending','approved','rejected')),approval_comments TEXT,version INTEGER NOT NULL DEFAULT 1,archived_at INTEGER,created_by TEXT NOT NULL REFERENCES users(id),CHECK(starts_at<ends_at),UNIQUE(school_id,id),FOREIGN KEY(school_id,assignment_id) REFERENCES teacher_assignments(school_id,id)
);
CREATE INDEX live_class_schedule ON school_live_classes(school_id,academic_year_id,section_id,starts_at);
CREATE TABLE live_class_link_launches(id TEXT PRIMARY KEY,school_id TEXT NOT NULL,live_class_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),launched_at INTEGER NOT NULL DEFAULT(unixepoch()),FOREIGN KEY(school_id,live_class_id) REFERENCES school_live_classes(school_id,id));
CREATE TRIGGER live_class_tenant_insert BEFORE INSERT ON school_live_classes WHEN NOT EXISTS(SELECT 1 FROM teacher_assignments WHERE school_id=NEW.school_id AND id=NEW.assignment_id AND academic_year_id=NEW.academic_year_id AND section_id=NEW.section_id AND teacher_user_id=NEW.teacher_user_id) OR NOT EXISTS(SELECT 1 FROM users WHERE school_id=NEW.school_id AND id=NEW.created_by AND user_type IN ('admin','teacher')) BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER live_class_tenant_update BEFORE UPDATE ON school_live_classes WHEN NEW.school_id!=OLD.school_id OR NEW.academic_year_id!=OLD.academic_year_id OR NEW.created_by!=OLD.created_by OR NOT EXISTS(SELECT 1 FROM teacher_assignments WHERE school_id=NEW.school_id AND id=NEW.assignment_id AND academic_year_id=NEW.academic_year_id AND section_id=NEW.section_id AND teacher_user_id=NEW.teacher_user_id) BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER link_launch_tenant BEFORE INSERT ON live_class_link_launches WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.actor_id AND school_id=NEW.school_id) BEGIN SELECT RAISE(ABORT,'TENANT_RELATIONSHIP'); END;
CREATE TRIGGER link_launch_no_update BEFORE UPDATE ON live_class_link_launches BEGIN SELECT RAISE(ABORT,'IMMUTABLE_LINK_LAUNCH'); END;
CREATE TRIGGER link_launch_no_delete BEFORE DELETE ON live_class_link_launches BEGIN SELECT RAISE(ABORT,'IMMUTABLE_LINK_LAUNCH'); END;
